import type { Metadata } from "next";
import { site } from "@/lib/site";

type PageMetadataInput = {
  // Pages pass a short title; the root layout template adds the brand and
  // full name. Pass `absolute` to skip the template.
  title: string | { absolute: string };
  description: string;
  path: string;
  // Drafts are noindexed until their TODOs are filled in.
  draft?: boolean;
};

// Social card generated by app/opengraph-image.tsx.
export const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.headline} ${site.name}, web development by ${site.owner}.`,
};

// openGraph and robots are replaced, not merged, between segments, and a
// page that sets openGraph drops the root opengraph-image. So every page
// builds them here, image included.
export function pageMetadata({
  title,
  description,
  path,
  draft = false,
}: PageMetadataInput): Metadata {
  const socialTitle =
    typeof title === "string" ? `${title} | ${site.name}` : title.absolute;

  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en",
      url: path,
      title: socialTitle,
      description,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [ogImage],
    },
    ...(draft && { robots: { index: false, follow: true } }),
  };
}
